CREATE TABLE push_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),endpoint text NOT NULL UNIQUE,data text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_deliveries(id bigserial PRIMARY KEY,alert_id uuid NOT NULL REFERENCES alerts(id) ON DELETE CASCADE,subscription_id uuid NOT NULL REFERENCES push_subscriptions(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),claimed_at timestamptz,delivered_at timestamptz,UNIQUE(alert_id,subscription_id));
